<?php namespace App\Jobs; use App\Core\Database;use App\Services\OperationsOrchestrator; final class AutomationJob{public function run():int{$s=Database::pdo()->query("SELECT * FROM domain_events WHERE processed_at IS NULL ORDER BY id LIMIT 100");$n=0;foreach($s as $e){(new OperationsOrchestrator)->handle($e['event_name'],json_decode($e['payload_json']??'{}',true)?:[]);Database::pdo()->prepare('UPDATE domain_events SET processed_at=NOW() WHERE id=?')->execute([$e['id']]);$n++;}return $n;}}